#!/usr/bin/env bash
# Tier 1 (Python always; Rust when `cargo` is on PATH, Tier 2 REQUIRES it: VBM_JSON_REQUIRE_CARGO=1): the ABI description and the generated language bindings.
#   1. abi/vbm_json.abi.json agrees with include/vbm_json.h and LeanJson/Tape.lean (scripts/check_abi.py), shown able to fail on 13 drifted variants.
#   2. The committed bindings equal what scripts/gen-bindings.sh regenerates (drift check), shown able to fail: each tampered generated file, and a missing one, is rejected.
#   3. libvbm_json.so is built (scripts/build_shared.sh); the shared vectors (vbm-json-vectors-1, JSONTestSuite included, generated by the Lean REFERENCE) run through the Python binding
#      (tests/bindings/test_python.py) and the Rust binding (bindings/rust/tests/vectors.rs): verdict, error code, and the value read back to the reference's canonical bytes, every row.
#   4. NEGATIVE self-tests: a corrupted expected verdict, code and canonical form each fail each binding's test; mutants of each generated tape reader each fail it.
# Why Rust is Tier 2 where cargo is absent: cargo is not pinned by mise.toml and Tier 1 must not depend on a toolchain we do not install; ubuntu-latest (CI) ships it, so CI's Tier 2 requires it.
# Run: mise exec -- scripts/test_bindings.sh
set -euo pipefail
cd "$(dirname "$0")/.."
. scripts/lib-ran.sh   # ran_case / ran_done / must_fail: the self-tests count what they executed and a refused tool is a failure (docs/decisions/0005-ran-evidence.md)
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT
changed() { cmp -s "$1" "$2" && { echo "test_bindings: self-test: the corruption of $3 changed nothing" >&2; exit 1; } || true; }

# 1. the description and the header
python3 scripts/check_abi.py --selftest; ran_case

# 2. the drift check
scripts/gen-bindings.sh --check; ran_case
gen=(bindings/python/vbm_json/_generated.py bindings/python/vbm_json/__init__.py bindings/rust/src/sys.rs bindings/rust/src/lib.rs)
for f in "${gen[@]}"; do
  [ -f "$f" ] || { echo "test_bindings: $f is missing" >&2; exit 1; }
  rm -rf "$tmp/drift"; mkdir -p "$tmp/drift"; cp -r bindings "$tmp/drift/"
  echo "# drift" >> "$tmp/drift/$f"
  must_fail "a tampered $f" scripts/gen-bindings.sh --check "$tmp/drift"
  rm "$tmp/drift/$f"
  must_fail "a missing $f" scripts/gen-bindings.sh --check "$tmp/drift"
done
echo "test_bindings: the committed bindings equal the regenerated ones; a tampered or missing generated file each fails the drift check"

# 3. the library and the vectors
scripts/build_shared.sh "$tmp/lib" >/dev/null
[ -x .lake/build/bin/vbm-json-vectors ] && [ -f .lake/build/lib/libvbm_x2djson_LeanJson.a ] || lake build vbm-json-vectors >/dev/null   # tier1 builds these once; concurrent lake runs in one tree are avoided
.lake/build/bin/vbm-json-vectors --n 4 --out "$tmp/v" >/dev/null
v="$tmp/v/vectors.jsonl"
export VBM_JSON_LIB="$tmp/lib/libvbm_json.so"
py() { python3 tests/bindings/test_python.py "$1" "${2:-bindings/python}"; }
py "$v"; ran_case   # the positive run: the control of the negative self-tests below
# 4. negative self-tests, Python
sed '0,/"verdict":"ok"/s//"verdict":"err"/' "$v" > "$tmp/c1.jsonl"; changed "$v" "$tmp/c1.jsonl" verdict
sed '0,/"code":"syntax"/s//"code":"depth"/' "$v" > "$tmp/c2.jsonl"; changed "$v" "$tmp/c2.jsonl" code
sed '0,/"canonical":"[0-9a-f]/s//"canonical":"ff/' "$v" > "$tmp/c3.jsonl"; changed "$v" "$tmp/c3.jsonl" canonical
for i in 1 2 3; do must_fail "python: corrupted row set $i" py "$tmp/c$i.jsonl"; done
pymutant() {  # pymutant NAME SED: a mutant of the generated Python tape reader must fail the vectors
  rm -rf "$tmp/m_$1"; mkdir -p "$tmp/m_$1"; cp -r bindings/python/vbm_json "$tmp/m_$1/"
  sed -i "$2" "$tmp/m_$1/vbm_json/_generated.py"; changed bindings/python/vbm_json/_generated.py "$tmp/m_$1/vbm_json/_generated.py" "python mutant $1"
  must_fail "python mutant $1" py "$v" "$tmp/m_$1"
}
pymutant kind 's/^KIND_STRING = 4/KIND_STRING = 3/'
pymutant shift 's/^TAPE_LEN_SHIFT = 8/TAPE_LEN_SHIFT = 7/'
pymutant dupkeys 's/out.append((k, v))/out.append((k, None))/'
pymutant errcode 's/^SYNTAX = 1/SYNTAX = 9/'
echo "test_bindings: python: corrupted verdict, code, canonical form and four reader mutants each fail"

# 5. Rust
if ! command -v cargo >/dev/null 2>&1; then
  if [ -n "${VBM_JSON_REQUIRE_CARGO:-}" ]; then echo "test_bindings: cargo is required here (Tier 2) and was not found" >&2; exit 1; fi
  echo "test_bindings: rust SKIPPED: cargo was not found on PATH (Tier 1 skips, Tier 2 requires it: scripts/tier2.sh)"; ran_done test_bindings; exit 0
fi
export CARGO_TARGET_DIR="$tmp/target" CARGO_BUILD_JOBS=2 VBM_JSON_LIB_DIR="$tmp/lib"
rs() { VBM_JSON_VECTORS="$1" cargo test --quiet --offline --manifest-path "${2:-bindings/rust}/Cargo.toml" -- --nocapture; }
rs "$v" 2>&1 | grep -E '^vectors: ' || { echo "test_bindings: the rust vectors test did not report" >&2; exit 1; }; ran_case
for i in 1 2 3; do must_fail "rust: corrupted row set $i" rs "$tmp/c$i.jsonl"; done
rsmutant() {  # rsmutant NAME FILE SED
  rm -rf "$tmp/r_$1"; mkdir -p "$tmp/r_$1"; cp -r bindings/rust/. "$tmp/r_$1/"
  sed -i "$3" "$tmp/r_$1/$2"; changed "bindings/rust/$2" "$tmp/r_$1/$2" "rust mutant $1"
  must_fail "rust mutant $1" rs "$v" "$tmp/r_$1"
}
rsmutant kind src/sys.rs 's/^pub const VBM_JSON_STRING: u64 = 4;/pub const VBM_JSON_STRING: u64 = 3;/'
rsmutant shift src/sys.rs 's/^pub const TAPE_LEN_SHIFT: u32 = 8;/pub const TAPE_LEN_SHIFT: u32 = 7;/'
rsmutant dupkeys src/lib.rs 's/members.push((k, v));/members.push((k, Value::Null));/'
rsmutant errcode src/sys.rs 's/^pub const VBM_JSON_SYNTAX: c_int = 1;/pub const VBM_JSON_SYNTAX: c_int = 9;/'
echo "test_bindings: rust: corrupted verdict, code, canonical form and four reader mutants each fail"
ran_done test_bindings
echo "test_bindings: ok"
